    expect(run(() => unpaidBookingGuard(route('1'), {} as never))).toBeInstanceOf(UrlTree);
    booking.addSeats(['R1C5']);
    expect(run(() => unpaidBookingGuard(route('1'), {} as never))).toBe(true);
